do $$
declare
  v_course_id uuid := 'bb0d0b5f-ebb4-4888-af6d-35c5915bf453';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
  v_m3 uuid;
begin
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where course_id = v_course_id;

  insert into public.levels (course_id, title, description, order_number) values
    (v_course_id, 'Core Security', 'The threats you''re actually defending against, how people and systems get compromised, and the authentication and cryptography fundamentals every later level builds on.', 2)
  returning id into v_level;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Common Threats & Attacks', 'The attack types behind most real-world breaches — phishing, malware, social engineering, password attacks, on-path attacks, denial of service, and zero-days.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Phishing: How It Works and How to Spot It', 'How phishing attacks trick people into handing over credentials or installing malware, and the concrete red flags that give a fake message away.', 'https://www.youtube.com/watch?v=BhGWnSeNXq0', 1,
      array['Define phishing and explain why it targets people, not systems', 'Identify common red flags in a phishing email or message', 'Explain the difference between phishing, spear phishing, and whaling'],
      'Phishing is an attempt to trick someone into giving up sensitive information (passwords, card numbers) or installing malware, usually via a message disguised as coming from someone trustworthy. Common red flags include urgency (''your account will be closed today''), mismatched sender addresses, generic greetings, and links that don''t actually point where they claim to. Spear phishing targets a specific person using researched personal details; whaling specifically targets executives. Phishing remains one of the most common entry points for real breaches because it attacks human judgment, not a technical weakness.',
      'Find 2-3 real phishing examples (search ''phishing email examples'') and identify at least 3 red flags in each one.',
      '[{"question":"What does phishing primarily target?","options":["A software vulnerability","Human judgment and trust","A network port","A database"],"correct_index":1},{"question":"Which is a common phishing red flag?","options":["A calm, no-rush tone","Urgency and threats of an account closing","A correctly spelled sender address","A personalized, accurate greeting"],"correct_index":1}]'::jsonb),
    (v_m1, 'Malware Explained: Viruses, Worms, Trojans, and Ransomware', 'A breakdown of the major malware categories and how each one actually behaves once it''s on a system.', 'https://www.youtube.com/watch?v=xXkevJcOBTw', 2,
      array['Distinguish viruses, worms, trojans, and ransomware', 'Explain how each type typically spreads', 'Identify why ransomware in particular has become so damaging'],
      'Malware is a catch-all term for malicious software, but the categories behave very differently. A virus attaches itself to a legitimate file and needs a human action (like opening it) to spread. A worm spreads on its own across a network without needing a host file. A trojan disguises itself as legitimate software to trick a user into installing it. Ransomware encrypts a victim''s files and demands payment for the decryption key — it''s become especially damaging because it directly monetizes an attack rather than just causing disruption or stealing data quietly.',
      'Look up one real, named ransomware attack (e.g. WannaCry, Colonial Pipeline) and write 3 sentences on how it spread and what its impact was.',
      '[{"question":"What makes a worm different from a virus?","options":["A worm needs a host file to spread; a virus doesn''t","A worm can spread on its own across a network without a host file","They are the same thing","Worms only affect mobile devices"],"correct_index":1},{"question":"What does ransomware do?","options":["Steals passwords silently","Encrypts files and demands payment for the decryption key","Only displays annoying pop-up ads","Slows down a computer''s fan"],"correct_index":1}]'::jsonb),
    (v_m1, 'Social Engineering: Manipulating People, Not Computers', 'The psychological techniques attackers use to manipulate people into bypassing security — often more effective than any technical exploit.', 'https://www.youtube.com/watch?v=DguyS42zWHM', 3,
      array['Define social engineering and explain why it works', 'Identify common social engineering techniques (pretexting, baiting, tailgating)', 'Explain why technical defenses alone can''t stop social engineering'],
      'Social engineering is manipulating a person into doing something that helps an attacker — handing over a password, holding a secure door open, or plugging in an infected USB drive. Pretexting invents a false scenario to build trust (e.g. posing as IT support). Baiting leaves something tempting (like a labeled USB drive) for a victim to pick up and use. Tailgating physically follows an authorized person through a secure door. These work because they exploit normal human helpfulness and trust rather than a system flaw, which is why awareness training matters as much as technical controls.',
      'Write a short (3-4 sentence) fictional example of a pretexting phone call an attacker might use to trick an employee into resetting a password, then list what should have tipped the employee off.',
      '[{"question":"What is ''tailgating'' in a security context?","options":["Sending phishing emails","Physically following an authorized person through a secure door","A type of malware","Cracking a password"],"correct_index":1},{"question":"Why can''t technical defenses alone stop social engineering?","options":["Firewalls block all social engineering automatically","It exploits human trust and behavior, not a technical flaw","Social engineering isn''t a real threat","It only happens online"],"correct_index":1}]'::jsonb),
    (v_m1, 'Password Attacks: Brute Force, Dictionary, and Credential Stuffing', 'How attackers actually try to guess or steal passwords at scale, and why password reuse makes credential stuffing so effective.', 'https://www.youtube.com/watch?v=-ZfbifHwEVE', 4,
      array['Distinguish brute force, dictionary, and credential stuffing attacks', 'Explain why password reuse across sites is especially dangerous', 'Identify why account lockouts and rate limiting help defend against these attacks'],
      'A brute force attack tries every possible character combination until one works — slow, but guaranteed to eventually succeed against a weak password. A dictionary attack is faster: it tries common real words and known-weak passwords first, since most people don''t pick truly random ones. Credential stuffing takes username/password pairs leaked from one breached site and tries them on other sites, banking on the fact that many people reuse the same password everywhere — this is why a breach on one unrelated site can compromise your account somewhere else entirely.',
      'Check (using an email you''re comfortable using) at haveibeenpwned.com whether any of your accounts have appeared in a known breach, and note what it recommends doing next.',
      '[{"question":"What does a dictionary attack try first?","options":["Every possible random character combination","Common real words and known-weak passwords","Only numbers","Nothing — it''s random"],"correct_index":1},{"question":"Why is credential stuffing effective?","options":["It exploits password reuse across different sites","It only works on old computers","It requires physical access","It targets hardware, not accounts"],"correct_index":0}]'::jsonb),
    (v_m1, 'Man-in-the-Middle (On-Path) Attacks Explained', 'How an attacker secretly intercepts communication between two parties — now commonly called an ''on-path'' attack in current security terminology.', 'https://www.youtube.com/watch?v=M_Af6_8JTuo', 5,
      array['Explain what an on-path (man-in-the-middle) attack is', 'Describe a real-world scenario where this attack happens (e.g. unsecured Wi-Fi)', 'Explain why encryption (like HTTPS) defends against this attack'],
      'An on-path attack (the term security certifications now use in place of the older ''man-in-the-middle'') happens when an attacker secretly positions themselves between two communicating parties, able to read or alter traffic without either side noticing. A classic example is an attacker on the same unsecured public Wi-Fi network intercepting unencrypted traffic. This is exactly why HTTPS matters: encrypted traffic is still interceptable, but unreadable and untamperable without the encryption key, which defeats most on-path attacks even if the attacker is technically ''in the middle.''',
      'Explain in your own words why using public Wi-Fi without a VPN is riskier for on-path attacks than using your home network, and what HTTPS specifically protects against in that scenario.',
      '[{"question":"What is another current term for a man-in-the-middle attack?","options":["Zero-day attack","On-path attack","Brute force attack","Social engineering"],"correct_index":1},{"question":"Why does HTTPS help defend against on-path attacks?","options":["It blocks all Wi-Fi networks","It encrypts traffic so an interceptor can''t read or tamper with it","It deletes the attacker''s access","It has no effect on this attack"],"correct_index":1}]'::jsonb),
    (v_m1, 'Denial of Service (DoS) and DDoS Attacks Explained', 'How attackers overwhelm a system or service with traffic to knock it offline, and why ''distributed'' makes DDoS attacks so much harder to stop.', 'https://www.youtube.com/watch?v=bDAY-oUP0DQ', 6,
      array['Explain what a DoS attack does to a target system', 'Explain how a DDoS attack differs from a simple DoS attack', 'Identify why availability (the ''A'' in the CIA Triad) is the target of these attacks'],
      'A Denial of Service (DoS) attack floods a target (a server, service, or network) with so much traffic or so many requests that it can''t respond to legitimate users — effectively taking it offline. A Distributed Denial of Service (DDoS) attack does the same thing but from many sources at once (often a botnet of compromised devices), making it much harder to block since traffic isn''t coming from one identifiable place. These attacks specifically target availability — one of the three pillars of the CIA Triad covered back in Level 1 — rather than trying to steal or alter data.',
      'Look up one real, named DDoS attack (e.g. the 2016 Dyn attack, or a more recent one) and write 2-3 sentences on its scale and impact.',
      '[{"question":"What does a DDoS attack primarily aim to disrupt?","options":["Confidentiality","Integrity","Availability","Authentication"],"correct_index":2},{"question":"What makes a DDoS attack harder to block than a simple DoS attack?","options":["It uses stronger encryption","Traffic comes from many distributed sources at once","It only targets one computer","It''s slower"],"correct_index":1}]'::jsonb),
    (v_m1, 'Zero-Day Vulnerabilities and Why They''re Dangerous', 'What makes a ''zero-day'' vulnerability uniquely dangerous — and why patching quickly matters so much once one becomes public.', 'https://www.youtube.com/watch?v=w5MV1Jeo76g', 7,
      array['Define a zero-day vulnerability', 'Explain why zero-days are especially dangerous compared to known vulnerabilities', 'Explain the role of patching in reducing zero-day risk over time'],
      'A zero-day vulnerability is a software flaw that''s unknown to the vendor (and has had ''zero days'' to be fixed) at the time it''s being exploited — meaning there''s no patch available yet. This makes zero-days especially dangerous: standard defenses that rely on known signatures or patches don''t help until the vendor becomes aware and releases a fix. Once a vulnerability is publicly known and patched, it stops being a zero-day — but unpatched systems remain vulnerable to it indefinitely, which is why fast patching (recall Level 1''s Equifax lesson) is one of the highest-leverage security habits an organization can have.',
      'Search for a recent (last 1-2 years) named zero-day vulnerability and write 2-3 sentences on what software it affected and how it was eventually fixed.',
      '[{"question":"What makes a vulnerability a ''zero-day''?","options":["It''s exactly zero years old","It''s unknown to the vendor with no patch available yet when exploited","It only affects day-zero of a product launch","It''s a type of malware"],"correct_index":1},{"question":"Why does patching matter so much for zero-days?","options":["It doesn''t help with zero-days","Once patched, a vulnerability stops being exploitable via that flaw for updated systems","Patches only fix cosmetic issues","Patching increases vulnerability"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Authentication & Access Control', 'How systems verify who you are and control what you''re allowed to do once they know — passwords, MFA, password managers, and access control principles.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Passwords: What Actually Makes One Strong', 'The real factors behind password strength — length, uniqueness, and unpredictability — and why common ''strength'' advice is often outdated.', 'https://www.youtube.com/watch?v=Zgv6DjNf7ac', 1,
      array['Explain why password length matters more than complexity rules alone', 'Identify why password uniqueness across sites matters', 'Describe what a passphrase is and why it can be both strong and memorable'],
      'Password strength mostly comes down to length and unpredictability, not just cramming in symbols. A long passphrase (several random unrelated words) is often both stronger against brute-force attacks and easier to remember than a short, complex-looking password like ''P@ssw0rd1''. Just as important as strength is uniqueness: reusing a password across sites means one breach anywhere exposes every account using that same password (recall the credential stuffing lesson). Modern best practice favors long, unique passwords per account over complex-but-reused ones.',
      'Create a passphrase (4-5 random unrelated words) for a mock account, and compare its estimated strength/memorability to a shorter ''complex'' password like ''Tr0ub4dor&3''.',
      '[{"question":"What generally matters more for password strength: length or complexity symbols alone?","options":["Complexity symbols alone","Length and unpredictability","Neither matters","Only the number of digits"],"correct_index":1},{"question":"Why is password uniqueness across sites important?","options":["It isn''t important","One breach can expose every account reusing that password","It makes passwords load faster","Sites require unique passwords by law everywhere"],"correct_index":1}]'::jsonb),
    (v_m2, 'Multi-Factor Authentication (MFA) Explained', 'How MFA adds a second layer of proof beyond a password, and why it stops most account takeovers even when a password is stolen.', 'https://www.youtube.com/watch?v=yCJyPPvM-xg', 2,
      array['Explain the three general factor categories (something you know/have/are)', 'Describe how MFA protects an account even if the password is compromised', 'Identify common MFA methods (authenticator app, SMS code, hardware key)'],
      'MFA requires proving your identity with more than one factor from different categories: something you know (a password), something you have (a phone or hardware key), or something you are (a fingerprint). Even if an attacker steals your password through phishing or a breach, they still can''t log in without also having your second factor. Authenticator apps (generating a rotating code) and hardware security keys are generally considered stronger than SMS codes, since SMS can be intercepted via SIM-swapping attacks — but any MFA is significantly better than none.',
      'Enable MFA on one real account you use (email, banking app, or similar) if you haven''t already, using an authenticator app if that option exists.',
      '[{"question":"What are the three general MFA factor categories?","options":["Password, username, email","Something you know, have, and are","First name, last name, birthday","Speed, strength, size"],"correct_index":1},{"question":"Why is an authenticator app generally considered stronger than SMS codes for MFA?","options":["It isn''t stronger","SMS can be intercepted via SIM-swapping attacks","Authenticator apps are slower","SMS is more secure by design"],"correct_index":1}]'::jsonb),
    (v_m2, 'Password Managers: Why and How to Use One', 'How a password manager lets you use a unique, strong password everywhere without memorizing dozens of them.', 'https://www.youtube.com/watch?v=-WpAGxBqxxo', 3,
      array['Explain the core problem a password manager solves', 'Describe how a password manager stores and protects saved passwords', 'Set up a password manager and generate one strong unique password with it'],
      'The password-uniqueness advice from the earlier lesson only works in practice if you have a way to manage dozens of different strong passwords — which is what a password manager does. It generates and stores a unique, random password for every site, encrypted behind one strong master password (and ideally MFA) you actually memorize. This turns ''use a unique strong password everywhere'' from an unrealistic ask into something genuinely manageable, and is one of the single highest-impact security habits an individual can adopt.',
      'Install a reputable password manager (e.g. Bitwarden) and use it to generate and save one new strong password for an account you control.',
      '[{"question":"What core problem does a password manager solve?","options":["It makes websites load faster","It lets you use unique strong passwords everywhere without memorizing them all","It removes the need for any password","It backs up your files"],"correct_index":1},{"question":"What protects the passwords stored inside a password manager?","options":["Nothing, they''re stored in plain text","One strong master password (encrypting the rest)","The website''s own password","A public key anyone can see"],"correct_index":1}]'::jsonb),
    (v_m2, 'Access Control and the Principle of Least Privilege', 'How access control models decide who can do what, and why giving people only the access they actually need limits the damage of a compromised account.', 'https://www.youtube.com/watch?v=9ANHcZwJfdQ', 4,
      array['Define the principle of least privilege', 'Explain why limiting access reduces the impact of a compromised account', 'Identify a real example of least privilege in an everyday system'],
      'Access control determines what an authenticated user is actually allowed to do — not everyone with a valid login should be able to do everything. The principle of least privilege says every account should have only the minimum access needed for its role, nothing more. This matters directly for security: if an attacker compromises an account with excessive privileges, the damage they can do is much greater than if that same account only had narrow, necessary access. It''s the same idea introduced with file permissions back in Level 1, applied at the level of entire systems and roles.',
      'Think of an app or system you use with different user roles (e.g. a shared document, a work tool) and describe one example of least privilege you''ve seen — someone having read-only access instead of edit access, for instance.',
      '[{"question":"What does the principle of least privilege recommend?","options":["Give every account full access for convenience","Give each account only the minimum access it actually needs","Remove all access controls","Give admin access to all new accounts by default"],"correct_index":1},{"question":"Why does least privilege limit the damage of a compromised account?","options":["It doesn''t limit damage","A compromised low-privilege account can do less harm than a high-privilege one","It makes passwords stronger","It prevents all breaches entirely"],"correct_index":1}]'::jsonb),
    (v_m2, 'Understanding Sessions and Cookies (Security Basics)', 'How a website remembers you''re logged in between page loads, and the security implications of how that state is stored and protected.', 'https://www.youtube.com/watch?v=NlvngHl0cdc', 5,
      array['Explain what a session is and why websites need one', 'Describe what a cookie is and its role in maintaining login state', 'Identify a basic security risk around session/cookie theft (session hijacking)'],
      'HTTP on its own doesn''t remember anything between requests, so websites use sessions to track that you''re logged in as you move between pages. A cookie is a small piece of data the browser stores and sends back with each request, often containing a session identifier that ties your browser to your logged-in session on the server. If an attacker steals that session cookie (e.g. via an on-path attack on an unencrypted connection), they can potentially impersonate the logged-in user without ever knowing the password — which is part of why secure, HTTPS-only cookies matter.',
      'Open your browser''s developer tools on a site you''re logged into (F12 > Application/Storage > Cookies) and look at what cookies are set, without changing anything.',
      '[{"question":"Why do websites use sessions?","options":["To slow down page loads","Because HTTP doesn''t remember state between requests on its own","To block all users","To replace passwords entirely"],"correct_index":1},{"question":"What can happen if an attacker steals a valid session cookie?","options":["Nothing, cookies are harmless","They can potentially impersonate the logged-in user","The website automatically blocks them","It only affects images loading"],"correct_index":1}]'::jsonb),
    (v_m2, 'Single Sign-On (SSO) Explained', 'How SSO lets one login work across multiple applications, and the security tradeoffs of centralizing authentication that way.', 'https://www.youtube.com/watch?v=Bv6NZlqqn48', 6,
      array['Explain what SSO does for a user logging into multiple applications', 'Describe the security benefit of centralizing authentication through SSO', 'Identify the tradeoff of SSO (a single compromised account affects multiple systems)'],
      'Single Sign-On lets a user log in once through a central identity provider and gain access to multiple separate applications without logging in again for each one — the familiar ''Sign in with Google'' or workplace login is SSO in action. It''s a real security benefit for organizations: fewer passwords for users to manage badly, and centralized control to instantly revoke access everywhere at once (e.g. when an employee leaves). The tradeoff is concentration of risk — if that one central SSO account is compromised, an attacker potentially gets access to everything connected to it, which is why SSO accounts are especially high-value targets for MFA.',
      'Identify 2-3 apps or services you use where you log in via ''Sign in with Google/Microsoft/Apple'' rather than a separate password, and note whether MFA is enabled on that central account.',
      '[{"question":"What does SSO let a user do?","options":["Log in once to access multiple connected applications","Create unlimited accounts","Bypass all security checks","Only works for email"],"correct_index":0},{"question":"What is the main security tradeoff of SSO?","options":["There is no tradeoff","A compromised central account can affect every connected system","It makes login slower","It only works on mobile"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Cryptography Basics', 'How encryption, hashing, and digital certificates actually protect data in practice — the concepts behind HTTPS, password storage, and secure communication.', v_module_offset + 3)
  returning id into v_m3;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m3, 'Encryption vs Hashing: What''s the Difference', 'The key distinction between encryption (reversible, for confidentiality) and hashing (one-way, for integrity) — two concepts that get confused constantly.', 'https://www.youtube.com/watch?v=sKU-vWTmhXY', 1,
      array['Define encryption and explain that it''s reversible with the right key', 'Define hashing and explain that it''s a one-way process', 'Identify which one is used for storing passwords, and why'],
      'Encryption transforms readable data into unreadable ciphertext, reversible back to the original with the correct key — used when data needs to be read again later (like a file or a message). Hashing transforms data into a fixed-size output that cannot be reversed back to the original — used to verify data hasn''t changed, or to check a value (like a password) without ever storing the original. This is exactly why passwords should be hashed, not encrypted: a system never needs to see your actual password again, only verify a new attempt produces the same hash.',
      'Try an online SHA-256 hash generator on a short piece of text, then change one character and hash it again — notice the completely different output (this property is called the avalanche effect).',
      '[{"question":"Which of these is reversible with the right key?","options":["Hashing","Encryption","Neither","Both equally"],"correct_index":1},{"question":"Why are passwords hashed rather than encrypted for storage?","options":["Hashing is faster to type","A system never needs to recover the original password, only verify a match","Encryption doesn''t exist for passwords","Hashing makes passwords visible to admins"],"correct_index":1}]'::jsonb),
    (v_m3, 'Symmetric vs Asymmetric Encryption Explained', 'The two fundamental approaches to encryption — one shared key vs. a public/private key pair — and where each is actually used.', 'https://www.youtube.com/watch?v=6uRI4o5EUkI', 2,
      array['Explain symmetric encryption and its key weakness (key distribution)', 'Explain asymmetric encryption and the public/private key concept', 'Identify why real systems (like HTTPS) often use both together'],
      'Symmetric encryption uses one shared key for both encrypting and decrypting — fast, but both parties need that same secret key, which creates a problem: how do you securely share the key in the first place? Asymmetric encryption solves this with a mathematically linked key pair: a public key (freely shared) encrypts data that only the matching private key (kept secret) can decrypt. Asymmetric encryption is slower, so real-world systems like HTTPS typically use asymmetric encryption just to securely exchange a symmetric key, then switch to fast symmetric encryption for the actual data.',
      'Explain in your own words, in 2-3 sentences, why HTTPS uses both types of encryption together instead of picking just one.',
      '[{"question":"What is the key weakness of symmetric encryption?","options":["It''s too slow to use","Securely sharing the one shared key is a challenge","It can''t be used online","It doesn''t actually encrypt anything"],"correct_index":1},{"question":"In asymmetric encryption, what is the public key used for?","options":["Decrypting all data","Encrypting data that only the matching private key can decrypt","Deleting files","Nothing, it''s just for show"],"correct_index":1}]'::jsonb),
    (v_m3, 'How HTTPS and TLS Keep Web Traffic Secure', 'What actually happens when a browser shows that padlock icon — how TLS establishes an encrypted connection between you and a website.', 'https://www.youtube.com/watch?v=hExRDVZHhig', 3,
      array['Explain what TLS does for a web connection', 'Describe the basic idea of the TLS handshake', 'Explain what the padlock icon in a browser actually confirms (and doesn''t confirm)'],
      'HTTPS is regular HTTP running over TLS (Transport Layer Security), which encrypts the connection between a browser and a website so on-path attackers can''t read or tamper with the traffic. The TLS handshake is where the browser and server agree on encryption methods and exchange keys (using asymmetric encryption) before switching to fast symmetric encryption for the actual session — combining the two encryption types from the previous lesson. Importantly, the padlock icon only confirms the connection is encrypted and the site''s identity was verified by a certificate authority — it does NOT mean the site itself is trustworthy or safe; phishing sites can have valid HTTPS too.',
      'Click the padlock icon on a website you''re visiting and view its certificate details — note the issuing certificate authority and the validity dates.',
      '[{"question":"What does TLS do for a web connection?","options":["Makes pages load slower on purpose","Encrypts the connection between browser and server","Blocks all cookies","Deletes browsing history"],"correct_index":1},{"question":"What does the padlock icon actually confirm?","options":["The site is completely safe and trustworthy","The connection is encrypted and identity was certificate-verified — not that the site''s content is safe","Nothing at all","The site has no ads"],"correct_index":1}]'::jsonb),
    (v_m3, 'Digital Signatures Explained', 'How a digital signature proves a message or file really came from who it claims, and hasn''t been altered since.', 'https://www.youtube.com/watch?v=wR5myD_Tjew', 4,
      array['Explain what a digital signature proves about a message or file', 'Describe how a private key creates a signature that a public key can verify', 'Identify a real-world use of digital signatures (e.g. signed software updates)'],
      'A digital signature uses asymmetric encryption in reverse: the sender signs a message using their private key, and anyone can verify that signature using the sender''s public key. This proves two things at once — authenticity (it really came from the holder of that private key) and integrity (the message hasn''t been altered since it was signed, since any change would break the signature). Software updates and legal documents commonly use digital signatures so recipients can verify they''re getting the real, untampered file from the real publisher.',
      'Look up how code-signing works for an app or OS you use (search ''[your OS] code signing'') and write 2-3 sentences on what it protects against.',
      '[{"question":"What does a valid digital signature prove?","options":["Nothing useful","Authenticity and that the message hasn''t been altered since signing","That the message is encrypted","That the sender used a strong password"],"correct_index":1},{"question":"Which key creates a digital signature?","options":["The public key","The private key","A shared symmetric key","No key is needed"],"correct_index":1}]'::jsonb),
    (v_m3, 'Digital Certificates Explained', 'How a certificate authority vouches for the connection between a public key and its real-world owner, making trust on the internet possible at scale.', 'https://www.youtube.com/watch?v=BUQ3oQ-ikQY', 5,
      array['Explain what a digital certificate contains and proves', 'Describe the role of a Certificate Authority (CA)', 'Explain why a certificate is what makes HTTPS trust actually work'],
      'A digital certificate binds a public key to a real-world identity (like a website''s domain) and is itself digitally signed by a trusted Certificate Authority (CA) — an organization whose job is to verify that identity before issuing the certificate. This is what makes the previous lesson''s digital signatures actually useful at internet scale: without a CA vouching for it, anyone could claim any public key belongs to any identity. When your browser shows a valid HTTPS padlock, it''s really trusting the certificate''s chain back to a CA it already trusts, not just trusting encryption in the abstract.',
      'View the certificate details on a website (click the padlock) and trace the ''certificate chain'' back to the root Certificate Authority.',
      '[{"question":"What does a digital certificate bind together?","options":["Two unrelated files","A public key and a real-world identity, vouched for by a CA","A password and a username","Two symmetric keys"],"correct_index":1},{"question":"What is the role of a Certificate Authority?","options":["To block malicious websites automatically","To verify identity and vouch for the public key/identity binding via a signed certificate","To generate passwords for users","To host websites"],"correct_index":1}]'::jsonb),
    (v_m3, 'Password Hashing Done Right: Salting and bcrypt', 'Why hashing a password isn''t enough on its own, and how salting plus a slow, purpose-built algorithm like bcrypt actually protects stored passwords.', 'https://www.youtube.com/watch?v=XJYdPBD6PyU', 6,
      array['Explain why a plain hash alone is vulnerable to precomputed ''rainbow table'' attacks', 'Define salting and explain how it defeats that attack', 'Explain why bcrypt is deliberately slow, and why that''s a security feature, not a flaw'],
      'Simply hashing a password isn''t enough: attackers can precompute hashes for common passwords (a ''rainbow table'') and instantly look up a match. Salting adds a unique random value to each password before hashing, so even identical passwords produce different hashes and precomputed tables become useless. bcrypt is a hashing algorithm purpose-built for passwords: it automatically handles salting and is deliberately slow and tunable, which sounds bad but is actually the point — it makes brute-forcing millions of guesses computationally expensive for an attacker, while a single legitimate login check stays fast enough not to matter.',
      'Explain in your own words why a fast, general-purpose hash algorithm (like plain SHA-256) is a worse choice for password storage than a slow, purpose-built one like bcrypt.',
      '[{"question":"What does salting a password before hashing protect against?","options":["Nothing, it''s cosmetic","Precomputed rainbow table attacks","Network attacks only","Phishing"],"correct_index":1},{"question":"Why is bcrypt''s deliberate slowness a security feature?","options":["It isn''t a feature, just a flaw","It makes brute-forcing many password guesses computationally expensive for attackers","It slows down the whole website","It has nothing to do with security"],"correct_index":1}]'::jsonb),
    (v_m3, 'Public Key Infrastructure (PKI) Basics', 'How all the pieces — key pairs, signatures, certificates, and Certificate Authorities — fit together into the trust system the whole internet relies on.', 'https://www.youtube.com/watch?v=xHAMEF7-inQ', 7,
      array['Explain what PKI is at a high level', 'Identify the core components of PKI (keys, certificates, CAs)', 'Explain why PKI is the foundation that makes HTTPS trust possible at internet scale'],
      'Public Key Infrastructure is the whole system that ties together everything from this module: key pairs, digital signatures, certificates, and Certificate Authorities, into one framework for establishing trust between parties who''ve never met. PKI is what lets your browser trust millions of websites it''s never seen before, purely because each one presents a certificate signed by a CA your browser already trusts. It''s not one single technology — it''s the combined infrastructure (policies, roles, and systems) that makes public-key cryptography usable at the scale of the entire internet.',
      'Draw or write out, in your own words, the chain of trust from ''you visit a website'' to ''your browser trusts it,'' naming each PKI component involved (certificate, CA, public/private key).',
      '[{"question":"What is PKI?","options":["A single encryption algorithm","The combined system of keys, certificates, and CAs that enables trust at scale","A type of malware","A password manager"],"correct_index":1},{"question":"Why does PKI matter for HTTPS specifically?","options":["It doesn''t relate to HTTPS","It''s what lets a browser trust websites it''s never encountered before via CA-signed certificates","It replaces the need for encryption","It only matters for email"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

